import {observe} from '@github/selector-observer'
import {remoteForm} from '@github-ui/remote-form'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import pageFocused from './github/page-focused'

// Minimum safe window dimensions to prevent tiny iframe embedding attacks
// These values are set to accommodate mobile app embedding while still
// preventing malicious tiny iframe attacks
export const MIN_WINDOW_WIDTH = 320
export const MIN_WINDOW_HEIGHT = 300

// Delay after focus before enabling the button (milliseconds)
export const FOCUS_DELAY_MS = 1000

/**
 * Security state for OAuth authorize button.
 * The button is only enabled when ALL conditions are met:
 * - Window has focus
 * - Page is visible
 * - Window dimensions meet minimum requirements
 * - Authorization container is fully visible in viewport
 */
export interface OAuthSecurityState {
  hasFocus: boolean
  isVisible: boolean
  meetsMinSize: boolean
  isInViewport: boolean
  focusDelayPassed: boolean
}

export function createSecurityState(): OAuthSecurityState {
  return {
    hasFocus: document.hasFocus(),
    isVisible: document.visibilityState === 'visible',
    meetsMinSize: window.innerWidth >= MIN_WINDOW_WIDTH && window.innerHeight >= MIN_WINDOW_HEIGHT,
    isInViewport: false, // Will be set by IntersectionObserver
    focusDelayPassed: false,
  }
}

export function isSecure(state: OAuthSecurityState): boolean {
  return state.hasFocus && state.isVisible && state.meetsMinSize && state.isInViewport && state.focusDelayPassed
}

export function updateButtonState(button: HTMLButtonElement, state: OAuthSecurityState): void {
  button.disabled = !isSecure(state)
}

/**
 * Sets up continuous security monitoring for the OAuth authorize button.
 * The button is disabled whenever any security condition fails, preventing
 * clickjacking and cross-window forgery attacks.
 */
function setupSecurityMonitoring(button: Element): void {
  if (!(button instanceof HTMLButtonElement)) return

  const state = createSecurityState()
  let focusDelayTimeout: ReturnType<typeof setTimeout> | null = null

  const updateButton = () => updateButtonState(button, state)

  // Start with button disabled
  button.disabled = true

  // --- Focus monitoring ---
  const handleFocusChange = () => {
    const hadFocus = state.hasFocus
    state.hasFocus = document.hasFocus()
    state.isVisible = document.visibilityState === 'visible'

    if (state.hasFocus && state.isVisible && !hadFocus) {
      // Focus regained - start delay timer
      state.focusDelayPassed = false
      if (focusDelayTimeout) clearTimeout(focusDelayTimeout)
      focusDelayTimeout = setTimeout(() => {
        state.focusDelayPassed = true
        updateButton()
      }, FOCUS_DELAY_MS)
    } else if (!state.hasFocus || !state.isVisible) {
      // Focus lost - immediately disable and reset delay
      state.focusDelayPassed = false
      if (focusDelayTimeout) {
        clearTimeout(focusDelayTimeout)
        focusDelayTimeout = null
      }
    }
    updateButton()
  }

  document.addEventListener('visibilitychange', handleFocusChange)
  window.addEventListener('focus', handleFocusChange)
  window.addEventListener('blur', handleFocusChange)

  // --- Window size monitoring using ResizeObserver ---
  const handleResize = () => {
    state.meetsMinSize = window.innerWidth >= MIN_WINDOW_WIDTH && window.innerHeight >= MIN_WINDOW_HEIGHT
    updateButton()
  }

  if ('ResizeObserver' in window) {
    const resizeObserver = new ResizeObserver(handleResize)
    resizeObserver.observe(document.documentElement)
  }
  handleResize() // Initial check

  // --- Viewport visibility monitoring using IntersectionObserver ---
  const authContainer = button.closest('.js-authorization-buttons')
  if (authContainer && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver(
      entries => {
        for (const entry of entries) {
          // Require full visibility (intersection ratio of 1.0)
          state.isInViewport = entry.intersectionRatio >= 1.0
          updateButton()
        }
      },
      {
        threshold: [0, 0.25, 0.5, 0.75, 1.0], // Multiple thresholds for granular detection
      },
    )
    observer.observe(authContainer)
  } else {
    // Fallback: assume visible if IntersectionObserver not available
    state.isInViewport = true
  }

  // Initial focus check - trigger the delay if already focused
  if (state.hasFocus && state.isVisible) {
    focusDelayTimeout = setTimeout(() => {
      state.focusDelayPassed = true
      updateButton()
    }, FOCUS_DELAY_MS)
  }
}

/**
 * Legacy behavior: enables the button once after page gains focus and delay passes.
 * Used when oauth_authorize_clickjacking_protection feature flag is disabled.
 */
async function legacyUpdateButtonOnPageFocused(button: Element): Promise<void> {
  if (!(button instanceof HTMLButtonElement)) return

  await pageFocused(document)
  await new Promise(resolve => setTimeout(resolve, FOCUS_DELAY_MS))
  button.disabled = false
}

function unclickableEvent(event: Event) {
  event.preventDefault()
}

async function enableManualRedirect(link: Element) {
  link.addEventListener('click', unclickableEvent)
  link.classList.add('color-fg-muted')

  await new Promise(resolve => setTimeout(resolve, 3000))

  link.classList.remove('color-fg-muted')
  link.removeEventListener('click', unclickableEvent)
}

observe('.js-authorization-buttons .js-oauth-authorize-btn', authorizeButton => {
  if (isFeatureEnabled('oauth_authorize_clickjacking_protection')) {
    setupSecurityMonitoring(authorizeButton)
  } else {
    legacyUpdateButtonOnPageFocused(authorizeButton)
  }
})

observe('#js-manual-authorize-redirect', manualAuthorizeLink => {
  enableManualRedirect(manualAuthorizeLink)
})

remoteForm('.js-toggler-container .js-set-approval-state', async function (form, wants) {
  const container = form.closest('.js-toggler-container')!
  container.classList.add('loading')
  const response = await wants.json()
  if (response.json.approval_state === 'approved') {
    container.classList.add('on')
  } else if (response.json.approval_state === 'denied') {
    container.classList.add('revoked')
    container.classList.remove('on')
  }
  container.classList.remove('loading')
})

// Settings -> Applications -> Organization access -> "Request access" button
remoteForm('.js-request-access-approval-form', async function (form, wants) {
  await wants.text()
  const id = form.getAttribute('data-container-id')!
  document.querySelector(`#${id}`)!.classList.add('on')
})
